import{_ as e,c as p,o as r,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"鹹","description":"高島易斷 - 鹹","frontmatter":{"title":"鹹","description":"高島易斷 - 鹹"},"headers":[],"relativePath":"classics/takashima/031.md","filePath":"classics/takashima/031.md"}'),i={name:"classics/takashima/031.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="鹹" tabindex="-1">鹹 <a class="header-anchor" href="#鹹" aria-label="Permalink to “鹹”">​</a></h1><h2 id="鹹-1" tabindex="-1">鹹 <a class="header-anchor" href="#鹹-1" aria-label="Permalink to “鹹”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>鹹：亨，利貞，取女吉。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《鹹》，亨通也。男女相合者七卦，《恆》是男女皆長，《既濟》、《未濟》中男中女，《漸》、《歸妹》以少遇長，《損》雖男女皆少，而女下於男，皆未若《鹹》之亨而正也。“娶女吉”者，婚禮自納采以至親迎，皆男下於女，六禮不備，貞女不行。《關雎》一篇所云，“窈窕淑女，君子好逑”，娶女之吉，於此可見。《詩·注》謂淑女有幽閒貞靜之德，是即“利貞”之旨也。《鹹》以《兌》澤《艮》山二氣相感，感而遂通，然少男少女，情好易通，得正則吉，失正則兇，故曰“利貞”。娶女之吉，惟其貞也。</p><h2 id="象辭" tabindex="-1">象辭 <a class="header-anchor" href="#象辭" aria-label="Permalink to “象辭”">​</a></h2><p>山上有澤，鹹，君子以虛受人。</p><h2 id="象辭注" tabindex="-1">象辭注 <a class="header-anchor" href="#象辭注" aria-label="Permalink to “象辭注”">​</a></h2><p>卦象為“山上有澤”，是山氣下交，澤氣上交，得以上下相成也。天下至靜而虛者莫如山，惟山以虛，翕受澤氣。君子體此象以容人之善，故能湛其心於寂然不動之時，定其性於廓然大公之地。古來如舜之取人為善，禹之拜昌言，周公之吐哺握髮，一皆虛己而受人者也。</p><h2 id="占斷" tabindex="-1">占斷 <a class="header-anchor" href="#占斷" aria-label="Permalink to “占斷”">​</a></h2><p>○　問戰徵：軍隊前進，防有坑陷，山谷間防有埋伏，固守城池，防敵兵潛通地道，皆當謹慎。</p><p>○　問營商：山澤為生財之地，即財源也。“以虛受人”，是以購入物產，販運轉售，必大獲利。</p><p>○　問功名：“山上”者高附之象，“山上有澤”，澤者，積水低窪之處。有居高思危之意，惟宜虛己待人，功名可長保也。</p><p>○　問家宅：是宅必傍山臨水，知其所止，吉。</p><p>○　問疾病：是虛弱之症，宜服滋補之劑。</p><p>○　問婚姻：卦為山澤通氣，主兩姓和好，大吉。</p><p>○　問訟事：兩造必是少年意氣相爭，訟宜和解而止為善。</p><p>○　問六甲：生男。</p><p>○　問失物：必墜入空洞有水之處，不能復得。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>“拇”者足之大指，初居爻首，為感之始，其感尚微，譬如足之有指，指即小動，未常移步，以喻人心初感而未動，始有其志而已。《象》曰“志在外也”，外謂九四，以初與四相應，故曰“在外”。志者心之所之也，謂第有其志，未嘗躁動，是以不言吉凶。</p><h2 id="初六佔" tabindex="-1">初六佔 <a class="header-anchor" href="#初六佔" aria-label="Permalink to “初六佔”">​</a></h2><p>○　問戰徵：是兵刃初交之會，應在第四日，可以得勝。</p><p>○　問營商：必是初次貿易，貨物已辦，尚未發行也。</p><p>○　問功名：必能一舉成名，有捷足先登之兆。</p><p>○　問家宅：有遷居外地之意。</p><p>○　問疾病：是足指初起一毒，宜外用敷藥調治。</p><p>○　問婚姻：初六應在九四，以《艮》男求婚於《兌》女也，為結縭之吉。</p><p>○　問六甲：生男，是初胎也。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>明治二十三年，佔某貴顯運氣，筮得《鹹》之《革》。</p><p>斷曰：此為《鹹》卦初爻，拇為足指，是人身最小之體，其動與不動，本不足關輕重也。初爻應在九四，四比近尊位，此佔當以應爻屬貴顯，初爻則為來佔之人也。今初爻《鹹》之初，某貴顯自幕府至今，備嘗困苦，今雖年老而志願猶奢，凡有指劃，《鹹》皆悅從。《象》曰：“志在外也”，蓋在貴顯之志，謂方今國家要務，專以外交為重也。知貴顯老運未艾。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>“腓”為脛，或曰足肚，是無骨之處，蓋在拇之上股之下也。腓不能自動，隨足而動，足動而兇，則腓亦失其吉矣。然動則為兇，而靜居則吉，故《象傳》曰；“雖兇居吉，順不害也。”六二以陰居陰，其性本靜，能順其性而不動，自可免害而獲吉也。</p><h2 id="六二佔" tabindex="-1">六二佔 <a class="header-anchor" href="#六二佔" aria-label="Permalink to “六二佔”">​</a></h2><p>○　問戰徵：宜固守不動，斯可免害。</p><p>○　問營商：不利行商，利坐賈。</p><p>○　問功名：只可依人成事，未能遠到。</p><p>○　問疾病：按腓病也，必是四肢痿痺之症，只可坐臥，不能步行也。</p><p>○　問婚姻：婚事既成，恐有變動，能以順自守，雖兇終吉。</p><p>○　問六甲：生男。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>華族某君來謂餘曰：頃者知己某，以數年刻苦，新創一技，特許專賣，餘因貸之以資金，但不知新創之技，果得廣行否？亦不知貸與之資金損益如何？請筮之。筮得《鹹》之《大過》。</p><p>斷曰：《鹹》者為山澤通氣之卦，是二物相依，相互為用也。某友發明一物，藉君之資金，得以成業，是某友與君實相依為用，其事業之廣行也可必矣。腓者足肚也，腓不自動，隨足之動而動，以喻資金之通用，全藉貨物之販運，而資金亦隨之而運動也。在此業新出，未免一時販售有礙，當居積以待，自能獲利，始雖兇而終吉也。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>此爻居下體之上，上體之下，為股之象，股者隨上下而動，不能自主者也。九三以陽居陽，與上六之陰相應，舍上六而比初二，以為動止，率此以往，其吝可知。三為《艮》卦之主，《艮》為股，故曰“股”，《艮》又為執，故曰“執”。《艮》本止也，三以感而思動，又牽率初二，使之皆動，故曰“執其隨”。《象傳》曰“亦不處也”，“亦”者，謂率拇腓而俱動也。“志在隨人，所執下也”，“隨人”者，謂隨上也；“執下”者，謂執初與二也。</p><h2 id="九三佔" tabindex="-1">九三佔 <a class="header-anchor" href="#九三佔" aria-label="Permalink to “九三佔”">​</a></h2><p>○　問戰徵：宜退守，不宜往攻。</p><p>○　問營商：凡商業合出資本，謂之股分，必舉一人以主其業，乃主業者，不能自主，而徒隨人以為上下，其業必難獲利。</p><p>○　問功名：隨聲附名，其品下矣，必難制勝。</p><p>○　問家宅：宅近《艮》山，本可安處，佔者不願處此，殆欲隨人他遷也，恐所往吝矣。</p><p>○　問婚姻：咎在過聽執柯者之言，恐所適非偶。</p><p>○　問六甲：生男。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>友人某來，請佔運氣，筮得《鹹》之《萃》。</p><p>斷曰：卦體《艮》山《兌》澤，山得澤而生潤，澤得山而發源，是為山澤通氣，陰陽相感，正元運旺相之象也。足下佔得第三爻，三爻為內卦之主，與上六相應，九三為陽，上六為陰，感而思動，故曰“鹹其股”。股屬下體，亦陰象也。卦本為少男少女兩相愛悅，三爻“志在隨人”，牽率其下而皆往，則其溺情尤甚，吝復何辭？論現年運氣，未嘗不佳，乃因溺志色慾，陽被陰累，防致疾厄，宜慎宜戒！友人聽之，始而如有所感，繼而溺情不悟，以致終身落魄不偶。哀哉！</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>四當三陽之中，居心之位，《鹹》之主也。初之拇，二之腓，三之股，五六之脢舌輔頰，皆從心而發，故心不言感，以萬感皆由心而生也。夫心之本體，本靈明不昧，寂然不動，自有所感而心動焉。動則有悔，欲其亡悔，惟貞而已；貞者正也，正則吉而悔亡。然人心不能無感，而感亦不能皆正，不正則心受其害，而悔隨感生，何以得吉？“憧憧”者急遽之狀，“往來”者忙促之形，“憧憧往來”，甚言紛至疊來，私意錯亂，害累叢生。下之拇、腓、股，上之脢、舌、輔，亦皆紛紛而動，但見其“朋從”耳，則此心豈復有一息之泰定哉！《象傳》曰“貞吉悔亡，未感害也”，謂貞則其心無私，未感之先，心本洞然，故曰“未感害也”。“憧憧往來，未光大也”，謂物感迭來，不能無思無慾，故曰“未光大也”。</p><h2 id="九四佔" tabindex="-1">九四佔 <a class="header-anchor" href="#九四佔" aria-label="Permalink to “九四佔”">​</a></h2><p>○　問戰徵：軍中全以主帥為心，當萬軍紛集，以一帥鎮定之，斯令行禁止，寂然不動，否則擾亂錯雜，災害生焉。</p><p>○　問營商：商務雖在謀利，亦以得貞為吉，若見利忘義，則群焉爭奪，不奪不饜，害有不可勝言者矣。</p><p>○　問功名：四爻以陽居陽，位近至尊，功名顯達，其象貞吉，然得不以正，害即隨之，最宜謹慎。</p><p>○　問家宅：其宅必臨通衢往來之地，邪正雜處，交際最宜慎擇。</p><p>○　問疾病：必是心神恍惚之症，宜靜養。</p><p>○　問婚姻：防女家閨範不謹。</p><p>○　問六甲：生女。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>明治二十二年，某縉紳來，請佔某貴顯氣運，筮得《鹹》之《蹇》。</p><p>斷曰：四爻以陽處陰，為內卦之始，比近九五，是貴顯之象也。為某貴顯佔氣運，筮得四爻，四當三陽之中，中居心位，心為百體之主，心貞則百體皆貞，猶言大臣正躬率物，百僚皆從令焉，故曰“貞吉悔亡”，此固某貴顯之能事也。苟心有不正，必致庶事叢脞，朋黨紛起，始則害在一身，終則害延一國，皆由一心之不正，階之厲也。在某貴顯，秉心正直，國而忘家，公而忘私，能以天下為己任，古所稱正一己以正天下者，某貴顯有焉，庶民所仰望者，正未有艾也。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>按：《注》雲“，脢者心上口下”，馬雲“脢背也”。《博雅》“胛謂之脢”，即背脢也；心在前，背在後，是不動之處也。《艮》之象曰“艮其背”，知背為《艮》之所止；爻辭曰“鹹其脢”，殆即孟子所云，“君子所性，根於心，盎於背，施於四體，四體不言而喻”者是也。五爻以陽剛中正之德，居君上之位，下應六二。六二日“鹹其腓”，腓為足肚，不能自動，五曰“鹹其脢”，脢為背脊，亦不能自動，故其《鹹》也，若有不感而感，而其動也，亦若有不動而動。不動而動，在脢亦不自知其動也，悔何有焉？《象傳》曰“志末”，謂此乃不感而感，感之至也。彼初之“志在外”，三之“志在隨人”，皆有心而感者，抑末矣。一說：《象傳》“志末也”者，謂尊居九五，當撫卹億兆之心，志願斯為大矣，若甘作自安之計，期免目前之悔，其志不亦微末乎？</p><h2 id="九五佔" tabindex="-1">九五佔 <a class="header-anchor" href="#九五佔" aria-label="Permalink to “九五佔”">​</a></h2><p>○　問戰徵：宜潛襲其後以攻敵背，有勝無敗。</p><p>○　問營商：《象》曰“志末”，末微小也，知其商業不大，利亦微薄。</p><p>○　問功名：背者，敗北也，知所求未必成名。</p><p>○　問疾病：臺背，壽徵也，知病即愈，無悔，且獲多壽。</p><p>○　問六甲：生女。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>明治二十一年，縉紳某來，請佔某貴顯氣運，筮得《鹹》之《小過》。</p><p>斷曰：凡卦例以九五為君位，然《乾》為君為父也，而臣子亦得佔之，《坤》為臣為民，而君父亦得佔之，《易》道不拘一例也。《鹹》卦《艮》山《兌》澤，二氣相感，是以“天地感而萬物化生，聖人感人心，而天下和平，則知大臣當國，皆以至誠感孚夫上下者也。今佔某貴顯氣運，得第五爻，爻辭曰“鹹其脢”，脢謂背脊處，前為陽，背為陰，心背之間，陰陽相感，亦痛疼相關。某貴顯念切民艱，自能恫痞在抱，不容以隔膜相視也，必無悔焉。至其後運，定臻臺背之壽，其福未可限量矣。《象傳》曰“志末也”，謂目下志願猶未光大也。</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>“輔”者，頰之裡，“頰”者輔之表，舌在口中，舌動則輔頰隨之。此爻陰柔不中，居卦之極，比近尊位，專以讒口惑君者也。是巧佞之小人，為聖人所深惡也，故不繫兇辭，而其兇自見矣。《象傳》曰“騰口說也”，騰謂張口騁辭，或曰虛也，謂無誠實，徒誇虛說以誑世，《鹹》道薄矣。</p><h2 id="上六佔" tabindex="-1">上六佔 <a class="header-anchor" href="#上六佔" aria-label="Permalink to “上六佔”">​</a></h2><p>○　問戰徵：防有間諜窺探。</p><p>○　問營商：恐有口舌之禍。</p><p>○　問功名：可獻策陳言，當得召用。</p><p>○　問家宅：主人口不睦，口角起爭。</p><p>○　問疾病：囈語譫言，心魂不安，宜禱。</p><p>○　問婚姻：中人之言，未可全信。</p><p>○　問六甲：生女。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>明治二十五年，巖平縣眾議院議員佐藤昌藏氏來曰：今回地租修正之議興，奧羽諸縣已編地租增加之部，然在我縣下，地質不饒，增加地租，甚覺不當為此，請佔院議結果。筮得《鹹》之《遁》。</p><p>斷曰：《兌》為口，輔頰舌皆所以言，此即議院之證驗也。今佔地租增加，而得《鹹》之上六，《鹹》者感也，凡有所議，必得上下直誠感通，其事可通行無阻。茲徒以空談相競而無實惠，其何能令民之遵從乎！後佐藤氏來謝曰：《易》斷真不虛也！</p>',94)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
